diff --git a/frontend/app/composables/use-token-cookie.ts b/frontend/app/composables/use-token-cookie.ts
index b6acb5f..4db8403 100644
--- a/frontend/app/composables/use-token-cookie.ts
+++ b/frontend/app/composables/use-token-cookie.ts
@@ -1,3 +1,10 @@
+const MAX_TIMEOUT_MS = 2 ** 31 - 1;
+const MIN_REFRESH_DELAY_MS = 30000;
+const MAX_JITTER_MS = 30000;
+
+/**
+ * Options for clearing the token cookie. The server owns the cookie's lifetime, so no maxAge is ever set here.
+ */
 export function getTokenCookieOptions() {
   const { $appInfo } = useNuxtApp();

@@ -5,9 +12,52 @@ export function getTokenCookieOptions() {
   const isEmbedded = isSecureConnection && window?.self !== window?.top;

   return {
-    maxAge: $appInfo.tokenTime * 60 * 60,
     secure: isSecureConnection,
     sameSite: (isEmbedded ? "none" : "lax") as "none" | "lax",
     partitioned: isEmbedded,
   };
 }
+
+/** The `exp` claim of a JWT in epoch milliseconds, or null if it cannot be read. */
+export function getTokenExpiry(token: string): number | null {
+  try {
+    const part = token.split(".")[1];
+    if (!part) return null;
+
+    const base64 = part.replace(/-/g, "+").replace(/_/g, "/");
+    const padded = base64 + "=".repeat((4 - (base64.length % 4)) % 4);
+    const bytes = Uint8Array.from(atob(padded), c => c.charCodeAt(0));
+    const payload = JSON.parse(new TextDecoder().decode(bytes));
+
+    return typeof payload?.exp === "number" ? payload.exp * 1000 : null;
+  }
+  catch {
+    return null;
+  }
+}
+
+/** The URL-decoded value of the named cookie in document.cookie, or null if it is absent. */
+export function readTokenCookie(name: string): string | null {
+  for (const entry of document.cookie.split(";")) {
+    const separator = entry.indexOf("=");
+    if (separator === -1) continue;
+    if (entry.slice(0, separator).trim() !== name) continue;
+
+    const raw = entry.slice(separator + 1).trim();
+    try {
+      return decodeURIComponent(raw);
+    }
+    catch {
+      return raw;
+    }
+  }
+  return null;
+}
+
+/** Milliseconds to wait before refreshing a token with `remainingMs` left to live, or null if it has expired. */
+export function nextRefreshDelay(remainingMs: number, jitter: number = Math.random()): number | null {
+  if (!(remainingMs > 0)) return null;
+
+  const delay = Math.max(remainingMs * 0.6, MIN_REFRESH_DELAY_MS) + jitter * MAX_JITTER_MS;
+  return Math.min(delay, MAX_TIMEOUT_MS);
+}
