@@ -1,9 +1,32 @@
+import { readTokenCookie } from "~/composables/use-token-cookie";
+
 export default defineNuxtPlugin({
   async setup() {
     const auth = useAuthBackend();
+    const tokenName = useRuntimeConfig().public.AUTH_TOKEN;

     console.debug("Initializing auth plugin");
+
+    // adopt the token the server put in the cookie so a background refresh is scheduled from its expiry
+    const adoptCookieToken = () => {
+      const token = readTokenCookie(tokenName);
+      if (token) {
+        auth.setToken(token);
+      }
+    };
+
+    adoptCookieToken();
     await auth.getSession();
+
+    // timers are throttled while the tab sleeps, so re-schedule when the user comes back or reconnects.
+    // This also follows tokens refreshed by other tabs, which share the cookie.
+    const reschedule = () => {
+      if (document.visibilityState !== "hidden") adoptCookieToken();
+    };
+    window.addEventListener("focus", reschedule);
+    window.addEventListener("online", reschedule);
+    document.addEventListener("visibilitychange", reschedule);
+
     console.debug("Auth plugin initialized");
   },
 });
