+def session_cookie_attrs(request: Request) -> dict[str, Any]:
+    """Attributes of the session cookie that depend on how the request reached the server"""
+    forwarded_proto = request.headers.get("x-forwarded-proto", "").split(",")[0].strip().lower()
+    try:
+        scheme = request.url.scheme
+    except KeyError:  # minimal ASGI scopes carry no path to build a URL from
+        scheme = request.scope.get("scheme", "http")
+    secure = scheme == "https" or forwarded_proto == "https"
+    embedded = request.headers.get("x-mealie-embedded", "").strip().lower() == "true"
+
+    # an embedded (framed) page can only send the cookie when it is SameSite=None and partitioned
+    cross_site = secure and embedded
+    samesite: Literal["lax", "none"] = "none" if cross_site else "lax"
+    return {"secure": secure, "samesite": samesite, "partitioned": cross_site}
