+async function loadInstance(): Promise<AxiosInstance> {
+  vi.resetModules();
+  vi.stubGlobal("defineNuxtPlugin", (plugin: unknown) => plugin);
+  vi.stubGlobal("useRuntimeConfig", () => ({ public: { AUTH_TOKEN: "mealie.access_token" } }));
+  vi.stubGlobal("useAuthBackend", () => ({ refresh, setToken }));
+
+  const plugin = (await import("../axios")).default as unknown as {
+    setup: (app: { runWithContext: <T>(fn: () => T) => T }) => { provide: { axios: AxiosInstance } };
+  };
+  return plugin.setup({ runWithContext: fn => fn() }).provide.axios;
+}
+
+function respondWith(instance: AxiosInstance, handler: (config: InternalAxiosRequestConfig) => number) {
+  const seen: InternalAxiosRequestConfig[] = [];
+  instance.defaults.adapter = async (config) => {
+    seen.push(config);
+    const status = handler(config);
+    const response = { data: {}, status, statusText: "", headers: {}, config };
+    if (status >= 400) {
+      throw Object.assign(new Error(`status ${status}`), { config, response, isAxiosError: true });
+    }
+    return response;
+  };
+  return seen;
+}
+
+describe("axios plugin", () => {
+  beforeEach(() => {
+    refresh.mockReset();
+    setToken.mockReset();
+    document.cookie = "mealie.access_token=old";
+  });
+
+  afterEach(() => {
+    document.cookie = "mealie.access_token=; Max-Age=0";
+    vi.unstubAllGlobals();
+  });
+
+  test("sends the cookie token as a bearer header", async () => {
+    const instance = await loadInstance();
+    const seen = respondWith(instance, () => 200);
+
+    await instance.get("/api/users/self");
+
+    expect(seen[0]!.headers.Authorization).toBe("Bearer old");
+  });
+
+  test("refreshes on 401 and replays the request once with the new token", async () => {
+    const instance = await loadInstance();
+    refresh.mockImplementation(async () => {
+      document.cookie = "mealie.access_token=new";
+    });
+    const seen = respondWith(instance, config => (config.headers.Authorization === "Bearer new" ? 200 : 401));
+
+    const response = await instance.get("/api/users/self");
+
+    expect(response.status).toBe(200);
+    expect(refresh).toHaveBeenCalledTimes(1);
+    expect(seen).toHaveLength(2);
+  });
+
+  test("an endpoint that always answers 401 refreshes once, then ends the session", async () => {
+    const instance = await loadInstance();
+    const location = { pathname: "/g/home/r/soup", search: "", href: "" };
+    vi.stubGlobal("location", location);
