+
+    await expect(instance.get("/api/users/self")).rejects.toBeTruthy();
+
+    expect(refresh).toHaveBeenCalledTimes(1);
+    expect(setToken).toHaveBeenCalledWith(null);
+    expect(location.href).toBe("/login?redirect=%2Fg%2Fhome%2Fr%2Fsoup");
+  });
+
+  test("401s from login, refresh and logout never refresh", async () => {
+    const instance = await loadInstance();
+    respondWith(instance, () => 401);
