+function answer(status: number, data: unknown = {}) {
+  return { status, data, statusText: "", headers: {}, config: {} as any };
+}
+
+function failWith401(): AxiosAdapter {
+  return (async (config: any) => Promise.reject({ config, response: answer(401) })) as AxiosAdapter;
+}
