 export default defineNuxtPlugin({
   async setup() {
     const auth = useAuthBackend();
+    const tokenName = useRuntimeConfig().public.AUTH_TOKEN;

     console.debug("Initializing auth plugin");
     await auth.getSession();
+
+    // Start the background refresh from the token's expiry
+    const startRefresh = () => {
+      const token = readTokenCookie(tokenName);
+      if (token) {
+        auth.setToken(token);
+      }
+    };
+    startRefresh();
+
+    // Timers stall while a device sleeps, so re-evaluate the schedule whenever the app comes back
+    window.addEventListener("focus", startRefresh);
+    window.addEventListener("online", startRefresh);
+    document.addEventListener("visibilitychange", () => {
+      if (document.visibilityState === "visible") {
+        startRefresh();
+      }
+    });
+
+    // Follow token changes made in other tabs (cookieStore is not available everywhere)
+    const cookieStore = (window as any).cookieStore;
+    cookieStore?.addEventListener?.("change", (event: { changed: { name: string }[]; deleted: { name: string }[] }) => {
+      if (event.changed.some(c => c.name === tokenName)) {
+        startRefresh();
+      }
+      else if (event.deleted.some(c => c.name === tokenName) && !readTokenCookie(tokenName)) {
+        auth.setToken(null);
+        auth.getSession();
+      }
+    });
+
     console.debug("Auth plugin initialized");
   },
 });
