+import time
+
+import jwt
+from fastapi.testclient import TestClient
+
+from mealie.core.config import get_app_settings
+from tests.utils import api_routes
+from tests.utils.fixture_schemas import TestUser
+
+
+def _login(api_client: TestClient, user: TestUser, remember_me: bool, password: str | None = None):
+    return api_client.post(
+        api_routes.auth_token,
+        data={"username": user.email, "password": password or user.password, "remember_me": str(remember_me).lower()},
+    )
+
+
+def test_login_sets_session_cookie(api_client: TestClient, unique_user: TestUser):
+    settings = get_app_settings()
+    lifetime = settings.TOKEN_TIME * 3600
+
+    for remember_me in (True, False):
+        response = _login(api_client, unique_user, remember_me)
+        assert response.status_code == 200
+        body = response.json()
+        assert body["expires_in"] == lifetime
+
+        payload = jwt.decode(body["access_token"], settings.SECRET, algorithms=["HS256"])
+        assert payload["rme"] is remember_me
+        assert payload["exp"] - payload["iat"] == lifetime
+
+        cookie = response.headers.raw[[k for k, _ in response.headers.raw].index(b"set-cookie")][1].decode()
+        assert cookie.startswith(f"mealie.access_token={body['access_token']}")
+        assert "Path=/" in cookie
+        assert "httponly" not in cookie.lower()
+        assert (f"Max-Age={lifetime}" in cookie) is remember_me
+
+
+def test_refresh_keeps_remember_me_and_refuses_api_tokens(api_client: TestClient, unique_user: TestUser):
+    body = _login(api_client, unique_user, True).json()
+    headers = {"Authorization": f"Bearer {body['access_token']}"}
+
+    response = api_client.post(api_routes.auth_refresh, headers=headers)
+    assert response.status_code == 200
+    assert "Max-Age=" in response.headers["set-cookie"]
+
+    new_headers = {"Authorization": f"Bearer {response.json()['access_token']}"}
+    assert api_client.get(api_routes.users_self, headers=new_headers).json()["id"] == str(unique_user.user_id)
+
+    assert api_client.get(api_routes.auth_refresh, headers=headers).status_code == 405
+    api_client.cookies.clear()
+    assert api_client.post(api_routes.auth_refresh).status_code == 401
+
+    created = api_client.post(api_routes.users_api_tokens, json={"name": "x"}, headers=unique_user.token).json()
+    response = api_client.post(api_routes.auth_refresh, headers={"Authorization": f"Bearer {created['token']}"})
+    assert response.status_code == 400
+
+    # other tests rely on the first token id, so leave nothing behind
+    api_client.delete(api_routes.users_api_tokens_token_id(created["id"]), headers=unique_user.token)
+
+
+def test_logout_clears_cookie(api_client: TestClient, unique_user: TestUser):
+    response = api_client.post(api_routes.auth_logout, headers=unique_user.token)
+    assert response.status_code == 200
+    assert response.headers["set-cookie"].startswith("mealie.access_token=")
+    assert "Max-Age=0" in response.headers["set-cookie"]
+
+
+def test_password_change_ends_existing_sessions(api_client: TestClient, unique_user_fn_scoped: TestUser):
+    unique_user = unique_user_fn_scoped
+    old_headers = {"Authorization": f"Bearer {_login(api_client, unique_user, False).json()['access_token']}"}
+    created = api_client.post(api_routes.users_api_tokens, json={"name": "x"}, headers=old_headers).json()
