+const SECONDS_PER_UNIT = [
+  ["day", 86400],
+  ["hour", 3600],
+  ["minute", 60],
+  ["second", 1],
+] as const;
+
+type DurationUnit = (typeof SECONDS_PER_UNIT)[number][0];
+
+function formatUnit(value: number, unit: DurationUnit, locale: string): string {
+  return new Intl.NumberFormat(locale, { style: "unit", unit, unitDisplay: "long" }).format(value);
+}
+
+/** Formats whole seconds as days, hours, minutes and seconds with the locale's long unit names, e.g. "1 hour 30 minutes" */
+export function formatDuration(seconds: number, locale: string): string {
+  let remaining = Math.max(0, Math.floor(seconds));
+  const parts: string[] = [];
+
+  for (const [unit, size] of SECONDS_PER_UNIT) {
+    const count = Math.floor(remaining / size);
+    remaining -= count * size;
+    if (count > 0) {
+      parts.push(formatUnit(count, unit, locale));
+    }
+  }
+
+  return parts.join(" ");
+}
+
+/** The locale's short name of a unit, e.g. "hr" or "min" in en-US */
+export function durationUnitLabel(unit: "hour" | "minute", locale: string): string {
+  const parts = new Intl.NumberFormat(locale, { style: "unit", unit, unitDisplay: "short" }).formatToParts(2);
+  return parts.find(part => part.type === "unit")?.value.trim() ?? unit;
+}
+
+/** The duration (when there is one) followed by the free text, e.g. "3 hours plus overnight" */
+export function recipeTimeDisplay(
+  seconds: number | null | undefined,
+  text: string | null | undefined,
+  locale: string,
+): string {
+  const parts = [seconds ? formatDuration(seconds, locale) : "", (text ?? "").trim()];
+  return parts.filter(part => part).join(" ");
+}
