+type DurationUnit = "day" | "hour" | "minute" | "second";
+
+const UNIT_SECONDS: [DurationUnit, number][] = [
+  ["day", 86400],
+  ["hour", 3600],
+  ["minute", 60],
+  ["second", 1],
+];
+
+function unitFormat(locale: string, unit: DurationUnit, unitDisplay: "long" | "short") {
+  return new Intl.NumberFormat(locale, { style: "unit", unit, unitDisplay, maximumFractionDigits: 0 });
+}
+
+/** Formats whole seconds as days, hours, minutes and seconds with the locale's long unit names. */
+export function formatDuration(seconds: number, locale: string): string {
+  let remaining = Math.max(0, Math.floor(seconds));
+  const parts: string[] = [];
+
+  for (const [unit, size] of UNIT_SECONDS) {
+    const count = Math.floor(remaining / size);
+    remaining -= count * size;
+    if (count > 0) {
+      parts.push(unitFormat(locale, unit, "long").format(count));
+    }
+  }
+
+  return parts.join(" ");
+}
+
+/** The locale's short name for a unit, e.g. "hr" or "min" in en-US. */
+export function durationUnitLabel(unit: "hour" | "minute", locale: string): string {
+  const part = unitFormat(locale, unit, "short")
+    .formatToParts(1)
+    .find(p => p.type === "unit");
+  return part?.value ?? unit;
+}
+
+/** The formatted duration (when set) followed by the free text (when set). */
+export function recipeTimeDisplay(
+  seconds: number | null | undefined,
+  text: string | null | undefined,
+  locale: string,
+): string {
+  const parts: string[] = [];
+
+  if (seconds) {
+    parts.push(formatDuration(seconds, locale));
+  }
+
+  const trimmed = (text ?? "").trim();
+  if (trimmed) {
+    parts.push(trimmed);
+  }
+
+  return parts.join(" ");
+}
