+from datetime import timedelta
+
+import pytest
+
+from mealie.lang.providers import get_locale_provider
+from mealie.routes.spa import iso_duration
+from mealie.services.scraper import cleaner
+
+
+@pytest.mark.parametrize(
+    "value,expected",
+    [
+        (True, None),
+        (30, 1800),
+        (1.5, 90),
+        ("30", 1800),
+        ("PT1H30M", 5400),
+        ("pt15m", 900),
+        ("P1DT1H", 90000),
+        ("P1W", 604800),
+        ("PT1M1.53S", 62),
+        ("", None),
+        ("1 hour 30 minutes", None),
+        ("P1M", None),
+        ("P1Y", None),
+        ("PT-3H", None),
+        (timedelta(hours=1), 3600),
+        ({"minValue": "PT1H"}, 3600),
+        (["PT1H", "PT2H"], 3600),
+        ([], None),
+        (None, None),
+        (0, None),
+        ("PT0M", None),
+        ("PT", None),
+        (-5, None),
+        ("P30000D", None),
+        (float("inf"), None),
+    ],
+)
+def test_clean_duration(value, expected):
+    assert cleaner.clean_duration(value) == expected
+
+
+def test_clean_time_rules():
+    translator = get_locale_provider()
+    assert cleaner.clean_time("P1M", translator) == "P1M"
+    assert cleaner.clean_time("-PT1H", translator) == "-PT1H"
+    assert cleaner.clean_time("PT-3H", translator) == "PT-3H"
+    assert cleaner.clean_time("P1W", translator) == "7 days"
+    assert cleaner.clean_time("P1DT1H1M1.53S", translator) == "1 day 1 hour 1 minute 1 second"
+    assert cleaner.clean_time(timedelta(0), translator) is None
+    assert cleaner.clean_time(-5, translator) is None
+
+
+def test_clean_stores_seconds():
+    translator = get_locale_provider()
+    recipe = cleaner.clean(
+        {"name": "Test Recipe", "totalTime": "PT1H30M", "prepTime": 20, "performTime": "about an hour"}, translator
+    )
+    assert (recipe.total_time_seconds, recipe.total_time) == (5400, None)
+    assert (recipe.prep_time_seconds, recipe.prep_time) == (1200, None)
+    assert (recipe.perform_time_seconds, recipe.perform_time) == (None, "about an hour")
+
+    recipe = cleaner.clean({"name": "Test Recipe", "totalTime": "PT2H", "totalTimeSeconds": 60}, translator)
+    assert (recipe.total_time_seconds, recipe.total_time) == (60, "2 hours")
+
+
+def test_iso_duration():
+    assert iso_duration(None) is None
+    assert iso_duration(0) is None
+    assert iso_duration(45) == "PT45S"
+    assert iso_duration(900) == "PT15M"
+    assert iso_duration(3690) == "PT1H1M30S"
+    assert iso_duration(93600) == "PT26H"
