+import pytest
+
+from tests.utils.alembic_reader import ALEMBIC_MIGRATIONS, import_file
+
+migration = import_file("structured_times", next(ALEMBIC_MIGRATIONS.glob("*27621d27c7e1*.py")))
+UNIT_WORDS = migration.load_unit_words()
+PATTERN = migration.build_component_pattern(UNIT_WORDS)
+
+
+@pytest.mark.parametrize(
+    "value,expected",
+    [
+        ("30", 1800),
+        ("1.5", 90),
+        ("PT15M", 900),
+        ("PT1H30M", 5400),
+        ("pt1h", 3600),
+        ("P1DT2H", 93600),
+        ("PT90S", 90),
+        ("1 hour 30 minutes", 5400),
+        ("1 Hour", 3600),
+        ("2 days 4 hours", 187200),
+        ("45 seconds", 45),
+        ("1 Stunde 30 Minuten", 5400),
+        ("2 heures 15 minutes", 8100),
+        ("1 時間 30 分", 5400),
+        ("1時間30分", 5400),
+        ("1.5 hours", 5400),
+        ("  20 minutes  ", 1200),
+        ("P1M", None),
+        ("P1Y", None),
+        ("PTXM", None),
+        ("about 30 minutes", None),
+        ("30 minutes, plus overnight", None),
+        ("1 hour and 30 minutes", None),
+        ("1 hour, 30 minutes", None),
+        ("Overnight", None),
+        ("none", None),
+        ("30 minutes 1 hour", None),
+        ("10 minutes 5 minutes", None),
+        ("30 mins", None),
+        ("1 hr", None),
+        ("0", None),
+        ("PT0M", None),
+        ("0 minutes", None),
+        ("PT0.5S", None),
+        ("0.001", None),
+        ("P30000D", None),
+        ("", None),
+        ("   ", None),
+        (None, None),
+    ],
+)
+def test_parse_seconds(value, expected):
+    assert migration.parse_seconds(value, UNIT_WORDS, PATTERN) == expected
+
+
+def test_load_unit_words(tmp_path):
+    (tmp_path / "aa-AA.json").write_text('{"datetime": {"hour": "tick|ticks", "minute": "min"}}')
+    (tmp_path / "bb-BB.json").write_text('{"datetime": {"second": "tick|tock"}}')
+    (tmp_path / "broken.json").write_text("{")
+    assert migration.load_unit_words(tmp_path) == {"ticks": "hour", "min": "minute", "tock": "second"}
+
+
+def test_upgrade_and_downgrade_convert_rows():
+    import sqlalchemy as sa
+    from alembic.migration import MigrationContext
+    from alembic.operations import Operations
+
+    engine = sa.create_engine("sqlite://")
+    with engine.begin() as conn:
+        conn.execute(
+            sa.text(
+                "CREATE TABLE recipes (id CHAR(32) PRIMARY KEY, total_time VARCHAR, prep_time VARCHAR, "
+                "perform_time VARCHAR, cook_time VARCHAR)"
+            )
+        )
+        conn.execute(
+            sa.text(
+                "INSERT INTO recipes VALUES ('0000000000000000000000000000000a', '1 hour 30 minutes', 'none', "
+                "'overnight', '10 minutes'), ('0000000000000000000000000000000b', NULL, '15', 'about an hour', NULL)"
+            )
+        )
+
+        with Operations.context(MigrationContext.configure(conn)):
+            migration.upgrade()
+            rows = [tuple(r[1:]) for r in conn.execute(sa.text("SELECT * FROM recipes ORDER BY id")).all()]
+            assert rows == [
+                (None, None, "overnight", "10 minutes", 5400, None, None),
+                (None, None, "about an hour", None, None, 900, None),
+            ]
+
+            migration.downgrade()
+            rows = [tuple(r[1:]) for r in conn.execute(sa.text("SELECT * FROM recipes ORDER BY id")).all()]
+            assert rows == [
+                ("1 hour 30 minutes", None, "overnight", "10 minutes"),
+                (None, "15 minutes", "about an hour", None),
+            ]
+
+    engine.dispose()
+
+
+def test_format_and_empty():
+    assert migration.format_seconds(60) == "1 minute"
+    assert migration.format_seconds(93690) == "1 day 2 hours 1 minute 30 seconds"
+    assert migration.is_empty_time(" None ") is True
+    assert migration.is_empty_time("none needed") is False
+    assert migration.is_empty_time(None) is False

