diff --git a/frontend/app/composables/recipes/use-recipe-time.ts b/frontend/app/composables/recipes/use-recipe-time.ts
new file mode 100644
index 0000000..a68612c
--- /dev/null
+++ b/frontend/app/composables/recipes/use-recipe-time.ts
@@ -0,0 +1,42 @@
+export type DurationUnit = "day" | "hour" | "minute" | "second";
+
+function formatUnit(value: number, unit: DurationUnit, locale: string, unitDisplay: "long" | "short"): string {
+  return new Intl.NumberFormat(locale, { style: "unit", unit, unitDisplay }).format(value);
+}
+
+/** Formats whole seconds as days, hours, minutes and seconds with the locale's long unit names, e.g. "1 hour 30 minutes" */
+export function formatDuration(seconds: number, locale: string): string {
+  const units: [DurationUnit, number][] = [
+    ["day", 86400],
+    ["hour", 3600],
+    ["minute", 60],
+    ["second", 1],
+  ];
+
+  let remaining = Math.max(0, Math.round(seconds));
+  const parts: string[] = [];
+  for (const [unit, size] of units) {
+    const count = Math.floor(remaining / size);
+    remaining -= count * size;
+    if (count) {
+      parts.push(formatUnit(count, unit, locale, "long"));
+    }
+  }
+
+  return parts.join(" ");
+}
+
+/** The locale's short name of a unit, e.g. "hr" or "min" in en-US */
+export function durationUnitLabel(unit: "hour" | "minute", locale: string): string {
+  const parts = new Intl.NumberFormat(locale, { style: "unit", unit, unitDisplay: "short" }).formatToParts(1);
+  return parts.find(part => part.type === "unit")?.value ?? unit;
+}
+
+/** The structured duration followed by the free text beside it, e.g. "3 hours plus overnight" */
+export function recipeTimeDisplay(
+  seconds: number | null | undefined,
+  text: string | null | undefined,
+  locale: string,
+): string {
+  return [seconds ? formatDuration(seconds, locale) : "", text?.trim() ?? ""].filter(Boolean).join(" ");
+}
