+def load_unit_words(locales_dir: Path = MESSAGES_DIR) -> dict[str, str]:
+    """Maps every unit word in the translations ("hour", "stunden", ...) to its unit name.
+
+    A word that more than one unit claims is ambiguous, so it is left out entirely.
+    """
+    words: dict[str, str] = {}
+    ambiguous: set[str] = set()
+
+    for file in sorted(Path(locales_dir).glob("*.json")):
+        try:
+            data = json.loads(file.read_text(encoding="utf-8"))
+        except OSError, ValueError:
+            continue
+
+        datetime_entries = data.get("datetime") if isinstance(data, dict) else None
+        if not isinstance(datetime_entries, dict):
+            continue
+
+        for unit in UNIT_SECONDS:
+            entry = datetime_entries.get(unit)
+            if not isinstance(entry, str):
+                continue
