+from datetime import timedelta
+
+import pytest
+
+from mealie.lang.providers import get_locale_provider as local_provider
+from mealie.routes.spa import iso_duration
+from mealie.schema.recipe.recipe import Recipe
+from mealie.services.scraper import cleaner
+from tests.utils.alembic_reader import ALEMBIC_MIGRATIONS, import_file
+
+migration = import_file("structured_times", next(ALEMBIC_MIGRATIONS.glob("*27621d27c7e1*.py")))
+UNIT_WORDS = migration.load_unit_words()
+PATTERN = migration.build_component_pattern(UNIT_WORDS)
+
+
+@pytest.mark.parametrize(
+    "value,expected",
+    [
+        ("30", 1800),
+        ("1.5", 90),
+        ("PT15M", 900),
+        ("PT1H30M", 5400),
+        ("pt1h", 3600),
+        ("P1DT2H", 93600),
+        ("PT90S", 90),
+        ("P1M", None),
+        ("P1Y", None),
+        ("PTXM", None),
+        ("1 hour 30 minutes", 5400),
+        ("1 Hour", 3600),
+        ("2 days 4 hours", 187200),
+        ("1 Stunde 30 Minuten", 5400),
+        ("2 heures 15 minutes", 8100),
+        ("1 時間 30 分", 5400),
+        ("1時間30分", 5400),
+        ("1.5 hours", 5400),
+        ("  20 minutes  ", 1200),
+        ("about 30 minutes", None),
+        ("30 minutes, plus overnight", None),
+        ("1 hour and 30 minutes", None),
+        ("1 hour, 30 minutes", None),
+        ("Overnight", None),
+        ("none", None),
+        ("30 minutes 1 hour", None),
+        ("10 minutes 5 minutes", None),
+        ("30 mins", None),
+        ("1 hr", None),
+        ("0", None),
+        ("PT0M", None),
+        ("0 minutes", None),
+        ("PT0.5S", None),
+        ("0.001", None),
+        ("P30000D", None),
+        (None, None),
+        ("  ", None),
+    ],
+)
+def test_parse_seconds(value, expected):
+    assert migration.parse_seconds(value, UNIT_WORDS, PATTERN) == expected
+
+
+def test_load_unit_words(tmp_path):
+    (tmp_path / "aa-AA.json").write_text('{"datetime": {"hour": "tick|ticks", "minute": "min"}}')
+    (tmp_path / "bb-BB.json").write_text('{"datetime": {"second": "tick|tock"}}')
+    (tmp_path / "broken.json").write_text("{")
+    assert migration.load_unit_words(tmp_path) == {"ticks": "hour", "min": "minute", "tock": "second"}
+
+
+def test_format_seconds_and_empty():
+    assert migration.format_seconds(60) == "1 minute"
+    assert migration.format_seconds(93690) == "1 day 2 hours 1 minute 30 seconds"
+    assert migration.is_empty_time(" None ") is True
+    assert migration.is_empty_time("none needed") is False
+    assert migration.is_empty_time(None) is False
+
+
+@pytest.mark.parametrize(
+    "value,expected",
+    [
+        (True, None),
+        (30, 1800),
+        (1.5, 90),
+        ("30", 1800),
+        ("PT1H30M", 5400),
+        ("pt15m", 900),
+        ("P1W", 604800),
+        ("PT1M1.53S", 62),
+        ("1 hour 30 minutes", None),
+        ("P1M", None),
+        ("PT-3H", None),
+        (timedelta(hours=1), 3600),
+        ({"minValue": "PT1H"}, 3600),
+        (["PT1H", "PT2H"], 3600),
+        (0, None),
+        ("PT", None),
+        (-5, None),
+        ("P30000D", None),
+        (float("inf"), None),
+    ],
+)
+def test_clean_duration(value, expected):
+    assert cleaner.clean_duration(value) == expected
+
+
+@pytest.mark.parametrize(
+    "value,expected",
+    [
+        (None, None),
+        (" ", None),
+        ("invalid", "invalid"),
+        ("PT2H30M", "2 hours 30 minutes"),
+        ("P1DT1H1M1.53S", "1 day 1 hour 1 minute 1 second"),
+        ("P1W", "7 days"),
+        ("PT", None),
+        ("PT0S", None),
+        (-5, None),
+        ("P1M", "P1M"),
+        ("-PT1H", "-PT1H"),
+        ("PT-3H", "PT-3H"),
+    ],
+)
+def test_clean_time(value, expected):
+    assert cleaner.clean_time(value, local_provider()) == expected
+
+
+def test_clean_recipe_times():
+    recipe = cleaner.clean(
+        {"name": "Test Recipe", "totalTime": "PT1H30M", "prepTime": 20, "performTime": "about an hour"},
+        local_provider(),
+    )
+    assert (recipe.total_time_seconds, recipe.total_time) == (5400, None)
+    assert (recipe.prep_time_seconds, recipe.prep_time) == (1200, None)
+    assert (recipe.perform_time_seconds, recipe.perform_time) == (None, "about an hour")
+
+    recipe = cleaner.clean({"name": "Test Recipe", "totalTime": "PT2H", "totalTimeSeconds": 60}, local_provider())
+    assert (recipe.total_time_seconds, recipe.total_time) == (60, "2 hours")
+
+
+def test_iso_duration():
+    assert iso_duration(None) is None
+    assert iso_duration(0) is None
+    assert iso_duration(45) == "PT45S"
+    assert iso_duration(3690) == "PT1H1M30S"
+    assert iso_duration(93600) == "PT26H"
+
+
+def test_seconds_validation():
+    assert Recipe(name="x", total_time_seconds=2147483647).total_time_seconds == 2147483647
+    for bad in (-1, 2147483648):
+        with pytest.raises(ValueError):
+            Recipe(name="x", total_time_seconds=bad)

