+import { flushPromises, mount, type VueWrapper } from "@vue/test-utils";
+import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";
+import GroupAIPromptEditor from "./GroupAIPromptEditor.vue";
+import type { AIPromptsOut } from "~/lib/api/types/group";
+
+const wrappers: VueWrapper[] = [];
+
+const mocks = vi.hoisted(() => ({
+  prompts: null as unknown as { value: AIPromptsOut | null },
+  refresh: vi.fn(),
+  save: vi.fn(),
+  reset: vi.fn(),
+}));
+
+vi.mock("~/composables/use-ai-providers", () => ({
+  useAIPrompts: () => ({
+    prompts: mocks.prompts,
+    loading: ref(false),
+    refresh: mocks.refresh,
+    save: mocks.save,
+    reset: mocks.reset,
+  }),
+}));
+
+vi.mock("~/composables/use-toast", () => ({
+  alert: { success: vi.fn(), error: vi.fn() },
+}));
+
+function response(overrides: Partial<AIPromptsOut> = {}): AIPromptsOut {
+  return {
+    globalInstructions: null,
+    prompts: [
+      { name: "recipes.build-recipe", isSystem: false, defaultContent: "BUILT-IN", mode: null, content: null, defaultChanged: false },
+      { name: "system.compile-source", isSystem: true, defaultContent: "SYSTEM", mode: null, content: null, defaultChanged: false },
+    ],
+    ...overrides,
+  };
+}
+
+function mountEditor() {
+  const wrapper = mount(GroupAIPromptEditor, {
+    global: {
+      mocks: { $globals: { icons: { alert: "alert" } } },
+      stubs: {
+        BaseButton: {
+          props: ["save", "disabled"],
+          template: "<button :disabled=\"disabled\" @click=\"$emit('click')\"><slot /></button>",
+        },
+        VTextarea: {
+          props: ["modelValue", "readonly"],
+          template: "<textarea :value=\"modelValue\" :readonly=\"readonly\" @input=\"$emit('update:modelValue', $event.target.value)\" />",
+        },
+        VBtnToggle: {
+          props: ["modelValue"],
+          template: "<div class=\"toggle\"><slot /></div>",
+        },
+        VBtn: { props: ["value"], template: "<button type=\"button\"><slot /></button>" },
+        VExpansionPanels: { template: "<div><slot /></div>" },
+        VExpansionPanel: { template: "<div><slot /></div>" },
+        VExpansionPanelTitle: { template: "<div><slot /></div>" },
+        VExpansionPanelText: { template: "<div><slot /></div>" },
+      },
+    },
+  });
+  wrappers.push(wrapper);
+  return wrapper;
+}
+
+describe("groupAIPromptEditor", () => {
+  beforeEach(() => {
+    mocks.prompts = ref(response());
+    mocks.refresh.mockReset().mockResolvedValue(null);
+    mocks.save.mockReset().mockResolvedValue(response());
+    mocks.reset.mockReset().mockResolvedValue(response());
+    vi.stubGlobal("useNuxtApp", () => ({ $globals: { icons: {} } }));
+  });
+
+  afterEach(() => {
+    wrappers.forEach(wrapper => wrapper.unmount());
+    wrappers.length = 0;
+    vi.unstubAllGlobals();
+  });
+
+  test("saving the group-wide instructions trims them and calls save('global')", async () => {
+    const wrapper = mountEditor();
+    await wrapper.find("textarea").setValue("  use metric  ");
