+    await flushPromises();
+    expect(wrapper.findAll("textarea")[1]!.element.value).toBe("");
+
+    await toggle.vm.$emit("update:modelValue", "override");
+    await flushPromises();
+    expect(wrapper.findAll("textarea")[1]!.element.value).toBe("My prompt");
+  });
+
+  test("saving in default mode resets, and a failed save keeps the user's text", async () => {
+    mocks.prompts = ref(response({
+      prompts: [
+        { name: "recipes.build-recipe", isSystem: false, defaultContent: "BUILT-IN", mode: "append", content: "extra", defaultChanged: false },
