+              :hint="$t('group.ai-prompts.default-hint')"
+              persistent-hint
+              readonly
+              auto-grow
+              rows="8"
+              variant="outlined"
+            />
+
+            <div class="d-flex mt-2">
+              <BaseButton save class="ml-auto" :disabled="!isDirty(prompt)" @click="savePrompt(prompt)" />
+            </div>
+          </template>
+        </v-expansion-panel-text>
+      </v-expansion-panel>
+    </v-expansion-panels>
+  </div>
+</template>
+
+<script setup lang="ts">
+import { alert } from "~/composables/use-toast";
+import { useAIPrompts } from "~/composables/use-ai-providers";
+import type { AIPromptOut, AIPromptsOut } from "~/lib/api/types/group";
+
+type EditorMode = "default" | "append" | "override";
+
+interface PromptState {
+  mode: EditorMode;
+  append: string;
+  override: string;
+}
+
+const MAX_LENGTH = 20000;
+
+const props = defineProps({
+  groupId: {
+    type: String,
+    default: undefined,
+  },
+});
+
+const i18n = useI18n();
+const { prompts, refresh, save, reset } = useAIPrompts(props.groupId);
+
+const globalText = ref("");
+const states = reactive<Record<string, PromptState | undefined>>({});
+
+// the saved (mode, content) each editor was last built from, so that only editors whose
+// saved data actually changed are rebuilt when a response comes in
+const synced: Record<string, string> = {};
+let syncedGlobal: string | null | undefined = undefined;
+
+function snapshot(prompt: AIPromptOut): string {
+  return JSON.stringify([prompt.mode ?? null, prompt.content ?? null]);
+}
+
+function buildState(prompt: AIPromptOut): PromptState {
+  return {
+    mode: prompt.mode ?? "default",
+    append: prompt.mode === "append" ? (prompt.content ?? "") : "",
+    override: prompt.mode === "override" ? (prompt.content ?? "") : "",
+  };
+}
+
+function syncState(response: AIPromptsOut | null) {
+  if (!response) {
+    return;
+  }
+
+  if (syncedGlobal === undefined || syncedGlobal !== (response.globalInstructions ?? null)) {
+    syncedGlobal = response.globalInstructions ?? null;
+    globalText.value = syncedGlobal ?? "";
+  }
+
+  for (const prompt of response.prompts) {
+    const current = snapshot(prompt);
+    if (!states[prompt.name] || synced[prompt.name] !== current) {
+      synced[prompt.name] = current;
+      states[prompt.name] = buildState(prompt);
+    }
+  }
+}
+
+watch(prompts, syncState, { immediate: true });
+
+// switching to an empty override editor starts from the built-in prompt; existing text is kept
+watch(
+  () => Object.values(states).map(state => state?.mode),
+  () => {
+    for (const prompt of prompts.value?.prompts ?? []) {
+      const state = states[prompt.name];
+      if (state && state.mode === "override" && !state.override.trim()) {
+        state.override = prompt.defaultContent;
+      }
+    }
+  },
+);
+
+onMounted(async () => {
+  await refresh();
+});
+
+const globalDirty = computed(() => globalText.value !== (prompts.value?.globalInstructions ?? ""));
+
+function editedText(state: PromptState): string {
+  return state.mode === "append" ? state.append : state.mode === "override" ? state.override : "";
+}
+
+function isDirty(prompt: AIPromptOut): boolean {
+  const state = states[prompt.name];
+  if (!state) {
+    return false;
+  }
+
+  const savedMode = prompt.mode ?? "default";
+  if (state.mode !== savedMode) {
+    return true;
+  }
+  return state.mode !== "default" && editedText(state) !== (prompt.content ?? "");
+}
+
+function notify(response: AIPromptsOut | null) {
+  if (response) {
+    alert.success(i18n.t("group.ai-prompts.saved"));
+  }
+  else {
+    alert.error(i18n.t("group.ai-prompts.save-failed"));
+  }
+}
+
+async function saveGlobal() {
+  const content = globalText.value.trim();
+  const response = content ? await save("global", { mode: "append", content }) : await reset("global");
+  if (response) {
+    globalText.value = content;
+  }
+  notify(response);
+}
+
+async function savePrompt(prompt: AIPromptOut) {
+  const state = states[prompt.name];
+  if (!state) {
+    return;
+  }
+
+  // an empty editor has nothing to send, which is the same as going back to the built-in prompt
+  if (state.mode === "default" || !editedText(state).trim()) {
+    notify(await reset(prompt.name));
+    return;
+  }
+
+  notify(await save(prompt.name, { mode: state.mode, content: editedText(state) }));
+}
+</script>
