+export function useAIPrompts(groupId?: string) {
+  const userApi = groupId ? null : useUserApi();
+  const adminApi = groupId ? useAdminApi() : null;
+
+  const prompts = ref<AIPromptsOut | null>(null);
+  const loading = ref(false);
+
+  async function run(request: () => Promise<RequestResponse<AIPromptsOut>>): Promise<AIPromptsOut | null> {
+    loading.value = true;
+    try {
+      const { data } = await request();
+      if (data) {
+        prompts.value = data;
+      }
+      return data ?? null;
+    }
+    finally {
+      loading.value = false;
+    }
+  }
+
+  function refresh() {
+    return run(() => (groupId ? adminApi!.aiProviders.getPrompts(groupId) : userApi!.aiProviders.getPrompts()));
+  }
+
+  function save(name: string, payload: AIPromptOverrideUpdate) {
