+  }
+
+  function reset(name: string) {
+    return run(() =>
+      groupId ? adminApi!.aiProviders.resetPrompt(groupId, name) : userApi!.aiProviders.resetPrompt(name),
+    );
+  }
+
+  return { prompts, loading, refresh, save, reset };
+}

