+from fastapi.testclient import TestClient
+
+from mealie.services.openai import OpenAIService
+from tests.utils import api_routes
+from tests.utils.fixture_schemas import TestUser
+
+NAME = "recipes.build-recipe"
+
+
+def _prompt(body: dict, name: str = NAME) -> dict:
+    return next(p for p in body["prompts"] if p["name"] == name)
+
+
+def test_get_prompts_lists_builtin_prompts(api_client: TestClient, unique_user: TestUser):
+    response = api_client.get(api_routes.groups_ai_providers_prompts, headers=unique_user.token)
+    assert response.status_code == 200
+
+    body = response.json()
+    assert body["globalInstructions"] is None
+    assert [p["name"] for p in body["prompts"]] == OpenAIService.get_prompt_names()
+    assert _prompt(body)["mode"] is None
+    assert _prompt(body)["defaultContent"] == OpenAIService.get_default_prompt(NAME)
+    assert _prompt(body, "system.compile-source")["isSystem"] is True
+
+
+def test_put_replaces_single_customization_and_delete_resets(api_client: TestClient, unique_user: TestUser):
+    url = api_routes.groups_ai_providers_prompts_prompt_name(NAME)
+    api_client.put(url, json={"mode": "append", "content": "first"}, headers=unique_user.token)
+    response = api_client.put(url, json={"mode": "override", "content": "second"}, headers=unique_user.token)
+    assert response.status_code == 200
+    assert _prompt(response.json())["mode"] == "override"
+    assert _prompt(response.json())["content"] == "second"
+    assert _prompt(response.json())["defaultChanged"] is False
+    assert len(unique_user.repos.group_ai_prompt_overrides.get_all()) == 1
+
+    response = api_client.delete(url, headers=unique_user.token)
+    assert response.status_code == 200
+    assert _prompt(response.json())["content"] is None
+    assert unique_user.repos.group_ai_prompt_overrides.get_all() == []
+
+    assert api_client.delete(url, headers=unique_user.token).status_code == 200
+
+
+def test_global_instructions(api_client: TestClient, unique_user: TestUser):
+    url = api_routes.groups_ai_providers_prompts_prompt_name("global")
+    response = api_client.put(url, json={"mode": "append", "content": "metric"}, headers=unique_user.token)
+    assert response.json()["globalInstructions"] == "metric"
+    assert api_client.put(url, json={"mode": "override", "content": "x"}, headers=unique_user.token).status_code == 400
+
+    response = api_client.delete(url, headers=unique_user.token)
+    assert response.json()["globalInstructions"] is None
+
+
+def test_invalid_prompt_requests(api_client: TestClient, unique_user: TestUser):
+    body = {"mode": "append", "content": "x"}
+    for name in ["recipes.does-not-exist", "debug", "..secrets"]:
+        url = api_routes.groups_ai_providers_prompts_prompt_name(name)
+        assert api_client.put(url, json=body, headers=unique_user.token).status_code == 404
+        assert api_client.delete(url, headers=unique_user.token).status_code == 404
+
+    url = api_routes.groups_ai_providers_prompts_prompt_name(NAME)
+    assert api_client.put(url, json={"mode": "append", "content": "   "}, headers=unique_user.token).status_code == 422
+
+
+def test_admin_sets_prompt_for_group(api_client: TestClient, admin_token, unique_user: TestUser):
+    url = api_routes.admin_groups_group_id_ai_providers_prompts_prompt_name(unique_user.group_id, NAME)
+    response = api_client.put(url, json={"mode": "override", "content": "admin"}, headers=admin_token)
+    assert response.status_code == 200
+    assert OpenAIService(unique_user.repos).get_prompt(NAME) == "admin"
+
+    assert api_client.put(url, json={"mode": "override", "content": "x"}, headers=unique_user.token).status_code == 403
+    list_url = api_routes.admin_groups_group_id_ai_providers_prompts(unique_user.group_id)
+    assert api_client.get(list_url, headers=admin_token).status_code == 200
+    assert api_client.delete(url, headers=admin_token).status_code == 200
