+++ b/tests/unit_tests/test_ai_prompt_overrides_migration.py
@@ -0,0 +1,64 @@
+import importlib.util
+from pathlib import Path
+
+import pytest
+import sqlalchemy as sa
+from alembic.migration import MigrationContext
+from alembic.operations import Operations
+
+from mealie.services.openai.openai import OpenAIService
+
+MIGRATION = next(Path(__file__).parents[2].glob("mealie/alembic/versions/*_a91720b8a7e7_*.py"))
+
+
+def _run_upgrade() -> list:
+    spec = importlib.util.spec_from_file_location("ai_prompt_overrides_migration", MIGRATION)
+    assert spec and spec.loader
+    module = importlib.util.module_from_spec(spec)
+    spec.loader.exec_module(module)
+
+    engine = sa.create_engine("sqlite://")
+    try:
+        with engine.begin() as conn:
+            conn.execute(sa.text("CREATE TABLE ai_provider_settings (id CHAR(32) PRIMARY KEY)"))
+            conn.execute(sa.text(f"INSERT INTO ai_provider_settings VALUES ('a{'0' * 31}')"))
+            with Operations.context(MigrationContext.configure(conn)):
+                module.upgrade()
+            return conn.execute(
+                sa.text(
+                    "SELECT settings_id, name, mode, content, base_prompt_hash FROM ai_prompt_overrides ORDER BY name"
+                )
+            ).fetchall()
+    finally:
+        engine.dispose()
+
+
+def test_upgrade_without_legacy_dir_only_creates_table(monkeypatch):
+    monkeypatch.delenv("OPENAI_CUSTOM_PROMPT_DIR", raising=False)
+    assert _run_upgrade() == []
+
+
+def test_upgrade_imports_legacy_prompt_files(monkeypatch, tmp_path):
+    (tmp_path / "recipes").mkdir()
+    (tmp_path / "general").mkdir()
+    (tmp_path / "recipes" / "build-recipe.txt").write_text("MINE")
+    (tmp_path / "recipes" / "compile-source.txt").write_text("SOURCE")
+    (tmp_path / "recipes" / "translate-recipe.txt").write_text("  \n")
+    (tmp_path / "recipes" / "scrape-recipe.txt").write_text("REMOVED")
+    (tmp_path / "general" / "debug.txt").write_text("DEBUG")
+    monkeypatch.setenv("OPENAI_CUSTOM_PROMPT_DIR", str(tmp_path))
+
+    rows = _run_upgrade()
+
+    assert [(r.name, r.mode, r.content) for r in rows] == [
+        ("recipes.build-recipe", "override", "MINE"),
+        ("system.compile-source", "override", "SOURCE"),
+    ]
+    assert all(r.settings_id == "a" + "0" * 31 for r in rows)
+    assert rows[0].base_prompt_hash == OpenAIService._hash_prompt(OpenAIService.get_default_prompt(rows[0].name))
+
+
+@pytest.mark.parametrize("value", ["", "/does/not/exist"])
+def test_upgrade_ignores_unusable_legacy_dir(monkeypatch, value):
+    monkeypatch.setenv("OPENAI_CUSTOM_PROMPT_DIR", value)
+    assert _run_upgrade() == []
