+import GroupAIPromptEditor from "./GroupAIPromptEditor.vue";
+import type { AIPromptsOut } from "~/lib/api/types/group";
+
+const wrappers: VueWrapper[] = [];
+
+const mocks = vi.hoisted(() => ({
+  save: vi.fn(),
+  reset: vi.fn(),
+  prompts: null as unknown,
+}));
+
+vi.mock("~/composables/use-ai-providers", () => ({
+  useAIPrompts: () => ({
+    prompts: mocks.prompts,
+    loading: ref(false),
+    refresh: vi.fn().mockResolvedValue(null),
+    save: mocks.save,
+    reset: mocks.reset,
+  }),
+}));
+
+vi.mock("~/composables/use-toast", () => ({
+  alert: { success: vi.fn(), error: vi.fn() },
+}));
+
+function response(): AIPromptsOut {
+  return {
+    globalInstructions: null,
+    prompts: [
+      { name: "recipes.build-recipe", isSystem: false, defaultContent: "BUILT-IN", mode: null, content: null, defaultChanged: false },
+      { name: "recipes.translate-recipe", isSystem: false, defaultContent: "TRANSLATE", mode: "override", content: "My prompt", defaultChanged: true },
+    ],
+  };
+}
+
+function mountEditor() {
+  mocks.prompts = ref(response());
+  const wrapper = mount(GroupAIPromptEditor, {
+    global: {
+      mocks: { $globals: { icons: { alert: "alert" } } },
+      stubs: {
+        BaseCardSectionTitle: { template: "<div />" },
+        BaseButton: { name: "BaseButton", props: ["save", "disabled"], template: "<button :disabled=\"disabled\"><slot /></button>" },
+        VTextarea: {
+          props: ["modelValue", "readonly"],
+          template: "<textarea :value=\"modelValue\" @input=\"$emit('update:modelValue', $event.target.value)\" />",
+        },
+        VBtnToggle: { name: "VBtnToggle", props: ["modelValue"], template: "<div><slot /></div>" },
+        VBtn: { props: ["value"], template: "<button><slot /></button>" },
+        VExpansionPanels: { template: "<div><slot /></div>" },
+        VExpansionPanel: { template: "<div><slot /></div>" },
+        VExpansionPanelTitle: { template: "<div><slot /></div>" },
+        VExpansionPanelText: { template: "<div><slot /></div>" },
+        VIcon: { template: "<i><slot /></i>" },
+      },
+    },
+  });
+  wrappers.push(wrapper);
+  return wrapper;
+}
+
+describe("groupAIPromptEditor", () => {
+  beforeEach(() => {
+    mocks.save.mockReset().mockResolvedValue(response());
+    mocks.reset.mockReset().mockResolvedValue(response());
+    vi.stubGlobal("useNuxtApp", () => ({ $globals: { icons: {} } }));
+  });
+
+  afterEach(() => {
+    wrappers.forEach(wrapper => wrapper.unmount());
+    wrappers.length = 0;
+    vi.unstubAllGlobals();
+  });
+
+  test("opens prompts in their saved mode", () => {
+    const wrapper = mountEditor();
+    const toggles = wrapper.findAllComponents({ name: "VBtnToggle" });
+
+    expect(toggles).toHaveLength(2);
+    expect(toggles[0]!.props("modelValue")).toBe("default");
+    expect(toggles[1]!.props("modelValue")).toBe("override");
+    expect((wrapper.findAll("textarea")[1]!.element as HTMLTextAreaElement).value).toBe("My prompt");
+  });
+
+  test("override keeps its text across mode switches and is filled from the default when empty", async () => {
+    const wrapper = mountEditor();
+    const toggle = wrapper.findAllComponents({ name: "VBtnToggle" })[0]!;
+
+    await toggle.vm.$emit("update:modelValue", "override");
+    expect((wrapper.findAll("textarea")[1]!.element as HTMLTextAreaElement).value).toBe("BUILT-IN");
+
+    await wrapper.findAll("textarea")[1]!.setValue("edited");
+    await toggle.vm.$emit("update:modelValue", "append");
+    await toggle.vm.$emit("update:modelValue", "override");
+    expect((wrapper.findAll("textarea")[1]!.element as HTMLTextAreaElement).value).toBe("edited");
+  });
+
+  test("saving calls save, reset, and the group-wide variants", async () => {
