+    await wrapper.findAll("textarea")[0]!.setValue("  metric  ");
+    await saveButtons[0]!.trigger("click");
+    expect(mocks.save).toHaveBeenCalledWith("global", { mode: "append", content: "metric" });
+
+    await wrapper.findAll("textarea")[0]!.setValue("   ");
+    await saveButtons[0]!.trigger("click");
+    expect(mocks.reset).toHaveBeenCalledWith("global");
+
+    await wrapper.findAll("textarea")[1]!.setValue("My prompt 2");
+    await saveButtons[2]!.trigger("click");
+    expect(mocks.save).toHaveBeenCalledWith("recipes.translate-recipe", { mode: "override", content: "My prompt 2" });
+    await flushPromises();
