+        {{ $t("group.ai-prompts.global-instructions") }}
+      </div>
+      <div class="text-caption mb-2">
+        {{ $t("group.ai-prompts.global-instructions-description") }}
+      </div>
+      <v-textarea
+        v-model="globalText"
+        auto-grow
+        rows="3"
+        variant="outlined"
+        hide-details
+      />
+      <div class="d-flex mt-2">
+        <BaseButton save class="ml-auto" :disabled="!globalDirty" @click="saveGlobal" />
+      </div>
+    </div>
+
+    <v-expansion-panels>
+      <v-expansion-panel v-for="prompt in prompts.prompts" :key="prompt.name">
+        <v-expansion-panel-title>
+          {{ prompt.name }}
+          <v-icon v-if="prompt.defaultChanged" class="ml-2" color="warning">
+            {{ $globals.icons.alert }}
+          </v-icon>
+        </v-expansion-panel-title>
+        <v-expansion-panel-text v-if="states[prompt.name]">
+          <div v-if="prompt.defaultChanged" class="text-warning mb-2">
+            {{ $t("group.ai-prompts.default-changed") }}
+          </div>
+          <div v-if="prompt.isSystem" class="text-caption mb-2">
+            {{ $t("group.ai-prompts.system-prompt") }}
+          </div>
+
+          <v-btn-toggle
+            v-model="states[prompt.name]!.mode"
+            mandatory
+            density="compact"
+            class="mb-3"
+            @update:model-value="onModeChange(prompt)"
+          >
+            <v-btn value="default">
+              {{ $t("group.ai-prompts.mode-default") }}
+            </v-btn>
+            <v-btn value="append">
+              {{ $t("group.ai-prompts.mode-append") }}
+            </v-btn>
+            <v-btn value="override">
+              {{ $t("group.ai-prompts.mode-override") }}
+            </v-btn>
+          </v-btn-toggle>
+
+          <div v-if="states[prompt.name]!.mode !== 'override'" class="mb-3">
+            <div class="text-caption">
+              {{ $t("group.ai-prompts.built-in-prompt") }}
+            </div>
+            <pre class="prompt-default">{{ prompt.defaultContent }}</pre>
+          </div>
+
+          <v-textarea
+            v-if="states[prompt.name]!.mode === 'append'"
+            v-model="states[prompt.name]!.append"
+            :label="$t('group.ai-prompts.append-label')"
+            auto-grow
+            rows="3"
+            variant="outlined"
+            hide-details
+          />
+          <v-textarea
+            v-else-if="states[prompt.name]!.mode === 'override'"
+            v-model="states[prompt.name]!.override"
+            :label="$t('group.ai-prompts.override-label')"
+            auto-grow
+            rows="8"
+            variant="outlined"
+            hide-details
+          />
+
+          <div class="d-flex mt-2">
+            <BaseButton save class="ml-auto" :disabled="!isDirty(prompt)" @click="savePrompt(prompt)" />
+          </div>
+        </v-expansion-panel-text>
+      </v-expansion-panel>
+    </v-expansion-panels>
+  </div>
+</template>
+
+<script setup lang="ts">
+import { useAIPrompts } from "~/composables/use-ai-providers";
+import { alert } from "~/composables/use-toast";
+import type { AIPromptOut } from "~/lib/api/types/group";
+
+type EditMode = "default" | "append" | "override";
+
+interface PromptState {
+  mode: EditMode;
+  append: string;
+  override: string;
+}
+
+const props = defineProps<{
+  groupId?: string;
+}>();
+
+const i18n = useI18n();
+const { prompts, refresh, save, reset } = useAIPrompts(props.groupId);
+
+const globalText = ref("");
+const globalSaved = ref("");
+const states = ref<Record<string, PromptState>>({});
+
+// Build editing state from the prompts response. Prompts the user is already editing keep
+// their unsaved text; only the saved baseline (read from `prompts`) moves.
+watch(
+  prompts,
+  (value) => {
+    if (!value) {
+      return;
+    }
+
+    globalSaved.value = value.globalInstructions || "";
+    if (!Object.keys(states.value).length) {
+      globalText.value = globalSaved.value;
+    }
+
+    for (const prompt of value.prompts) {
+      if (states.value[prompt.name]) {
+        continue;
+      }
+
+      states.value[prompt.name] = {
+        mode: prompt.mode || "default",
+        append: prompt.mode === "append" ? prompt.content || "" : "",
+        override: prompt.mode === "override" ? prompt.content || "" : "",
+      };
+    }
+  },
+  { immediate: true },
+);
+
+onMounted(refresh);
+
+const globalDirty = computed(() => globalText.value !== globalSaved.value);
+
+function onModeChange(prompt: AIPromptOut) {
+  const state = states.value[prompt.name];
+  if (state && state.mode === "override" && !state.override) {
+    state.override = prompt.defaultContent;
+  }
+}
+
+function isDirty(prompt: AIPromptOut): boolean {
+  const state = states.value[prompt.name];
+  if (!state) {
+    return false;
+  }
+
+  const savedMode: EditMode = prompt.mode || "default";
+  if (state.mode !== savedMode) {
+    return true;
+  }
+  if (state.mode === "default") {
+    return false;
+  }
+
+  return state[state.mode] !== (prompt.content || "");
+}
+
+async function savePrompt(prompt: AIPromptOut) {
+  const state = states.value[prompt.name];
+  if (!state) {
+    return;
+  }
+
+  const result = state.mode === "default"
+    ? await reset(prompt.name)
+    : await save(prompt.name, { mode: state.mode, content: state[state.mode] });
+
+  notify(result, state.mode === "default" ? "group.ai-prompts.reset" : "group.ai-prompts.saved");
+}
+
+async function saveGlobal() {
+  const content = globalText.value.trim();
+  const result = content ? await save("global", { mode: "append", content }) : await reset("global");
+
+  if (result) {
+    globalText.value = content;
+  }
+  notify(result, content ? "group.ai-prompts.saved" : "group.ai-prompts.reset");
+}
+
+function notify(result: unknown, successKey: string) {
+  if (result) {
+    alert.success(i18n.t(successKey));
+  }
+  else {
+    alert.error(i18n.t("group.ai-prompts.save-failed"));
+  }
+}
+</script>
+
+<style scoped>
+.prompt-default {
+  white-space: pre-wrap;
+  max-height: 200px;
+  overflow-y: auto;
+  font-size: 0.8rem;
+  opacity: 0.7;
+}
+</style>
