+
+/**
+ * A group's AI prompt customizations. Pass a groupId to manage another group as an admin;
+ * every call resolves to the new prompts, or null when the request failed.
+ */
+export function useAIPrompts(groupId?: string) {
+  const userApi = useUserApi();
+  const adminApi = useAdminApi();
+  const prompts = ref<AIPromptsOut | null>(null);
+  const loading = ref(false);
+
+  async function run(request: () => Promise<{ data: AIPromptsOut | null; error?: unknown }>) {
+    loading.value = true;
+    try {
+      const { data } = await request();
+      if (data) {
+        prompts.value = data;
+      }
+      return data || null;
+    }
+    catch {
+      return null;
+    }
+    finally {
+      loading.value = false;
+    }
+  }
+
+  function refresh() {
+    return run(() => groupId ? adminApi.aiProviders.getPrompts(groupId) : userApi.aiProviders.getPrompts());
+  }
+
+  function save(name: string, payload: AIPromptUpdate) {
+    return run(() =>
+      groupId
+        ? adminApi.aiProviders.savePrompt(groupId, name, payload)
+        : userApi.aiProviders.savePrompt(name, payload),
+    );
+  }
+
+  function reset(name: string) {
+    return run(() => groupId ? adminApi.aiProviders.resetPrompt(groupId, name) : userApi.aiProviders.resetPrompt(name));
+  }
+
+  return { prompts, loading, refresh, save, reset };
+}
