+from fastapi.testclient import TestClient
+
+from mealie.services.openai.openai import GLOBAL_PROMPT_NAME, OpenAIService
+from tests.utils.fixture_schemas import TestUser
+
+URL = "/api/groups/ai-providers/prompts"
+NAME = "recipes.build-recipe"
+
+
+def _prompt(data: dict, name: str) -> dict:
+    return next(p for p in data["prompts"] if p["name"] == name)
+
+
+def test_get_prompts_lists_builtin_prompts(api_client: TestClient, unique_user: TestUser):
+    response = api_client.get(URL, headers=unique_user.token)
+    assert response.status_code == 200
+    data = response.json()
+
+    assert data["globalInstructions"] is None
+    assert [p["name"] for p in data["prompts"]] == OpenAIService.get_prompt_names()
+    assert GLOBAL_PROMPT_NAME not in [p["name"] for p in data["prompts"]]
+    assert _prompt(data, "system.compile-source")["isSystem"] is True
+    assert _prompt(data, NAME)["defaultContent"] == OpenAIService.get_default_prompt(NAME)
+
+
+def test_save_replaces_and_reset_removes(api_client: TestClient, unique_user: TestUser):
+    api_client.put(f"{URL}/{NAME}", json={"mode": "append", "content": "first"}, headers=unique_user.token)
+    override = {"mode": "override", "content": "second"}
+    response = api_client.put(f"{URL}/{NAME}", json=override, headers=unique_user.token)
+    prompt = _prompt(response.json(), NAME)
+    assert (prompt["mode"], prompt["content"], prompt["defaultChanged"]) == ("override", "second", False)
+
+    response = api_client.delete(f"{URL}/{NAME}", headers=unique_user.token)
+    assert response.status_code == 200
+    assert _prompt(response.json(), NAME)["mode"] is None
+    assert api_client.delete(f"{URL}/{NAME}", headers=unique_user.token).status_code == 200
+
+
+def test_global_instructions(api_client: TestClient, unique_user: TestUser):
+    response = api_client.put(f"{URL}/global", json={"mode": "override", "content": "x"}, headers=unique_user.token)
+    assert response.status_code == 400
+
+    response = api_client.put(f"{URL}/global", json={"mode": "append", "content": "metric"}, headers=unique_user.token)
+    assert response.json()["globalInstructions"] == "metric"
+    assert all(p["mode"] is None for p in response.json()["prompts"])
+
+    response = api_client.delete(f"{URL}/global", headers=unique_user.token)
+    assert response.json()["globalInstructions"] is None
+
+
+def test_invalid_input(api_client: TestClient, unique_user: TestUser):
+    body = {"mode": "append", "content": "x"}
+    for name in ["recipes.nope", "debug", "..secrets"]:
+        assert api_client.put(f"{URL}/{name}", json=body, headers=unique_user.token).status_code == 404
+        assert api_client.delete(f"{URL}/{name}", headers=unique_user.token).status_code == 404
+
+    blank = {"mode": "append", "content": "   "}
+    assert api_client.put(f"{URL}/{NAME}", json=blank, headers=unique_user.token).status_code == 422
+
+
+def test_admin_routes_apply_to_group(api_client: TestClient, admin_user: TestUser, unique_user: TestUser):
+    url = f"/api/admin/groups/{unique_user.group_id}/ai-providers/prompts"
+    response = api_client.put(f"{url}/{NAME}", json={"mode": "append", "content": "extra"}, headers=admin_user.token)
+    assert _prompt(response.json(), NAME)["content"] == "extra"
+    assert api_client.get(url, headers=unique_user.token).status_code == 403
+
+    response = api_client.get(URL, headers=unique_user.token)
+    assert _prompt(response.json(), NAME)["content"] == "extra"
