+    (tmp_path / "recipes" / "compile-source.txt").write_text("custom compile")
+    (tmp_path / "recipes" / "translate-recipe.txt").write_text("  \n")
+    (tmp_path / "recipes" / "scrape-recipe.txt").write_text("removed prompt")
+    (tmp_path / "general" / "debug.txt").write_text("debug")
+
+    rows = _run(monkeypatch, tmp_path, tmp_path)
+
+    assert sorted((r[0], r[1], r[2], r[3]) for r in rows) == [
+        ("aa", "recipes.build-recipe", "override", "custom build"),
+        ("aa", "system.compile-source", "override", "custom compile"),
+        ("bb", "recipes.build-recipe", "override", "custom build"),
+        ("bb", "system.compile-source", "override", "custom compile"),
+    ]
+    expected = OpenAIService._hash_prompt(OpenAIService.get_default_prompt("recipes.build-recipe"))
+    assert next(r[4] for r in rows if r[1] == "recipes.build-recipe") == expected
