+<template>
+  <div v-if="prompts">
+    <h3 class="text-h6">
+      {{ $t("group.ai-prompts.ai-prompts") }}
+    </h3>
+    <p class="pb-6">
+      {{ $t("group.ai-prompts.ai-prompts-description") }}
+    </p>
+
+    <div class="mb-6">
+      <v-textarea
+        v-model="globalText"
+        :label="$t('group.ai-prompts.global-instructions')"
+        :hint="$t('group.ai-prompts.global-instructions-description')"
+        persistent-hint
+        auto-grow
+        rows="3"
+        variant="outlined"
+        density="compact"
+      />
+      <div class="d-flex pt-2">
+        <BaseButton
+          save
+          class="ml-auto"
+          :disabled="!globalDirty"
+          @click="saveGlobal"
+        />
+      </div>
+    </div>
+
+    <v-expansion-panels variant="accordion">
+      <v-expansion-panel
+        v-for="entry in entries"
+        :key="entry.name"
+      >
+        <v-expansion-panel-title>
+          <span>{{ entry.name }}</span>
+          <v-icon
+            v-if="entry.defaultChanged"
+            size="small"
+            color="warning"
+            class="ms-2"
+            :title="$t('group.ai-prompts.default-changed')"
+          >
+            {{ $globals.icons.alert }}
+          </v-icon>
+        </v-expansion-panel-title>
+        <v-expansion-panel-text>
+          <p v-if="entry.isSystem" class="text-caption mb-2">
+            {{ $t("group.ai-prompts.system-prompt-description") }}
+          </p>
+          <p v-if="entry.defaultChanged" class="text-caption text-warning mb-2">
+            {{ $t("group.ai-prompts.default-changed-description") }}
+          </p>
+
+          <v-btn-toggle
+            :model-value="entry.mode"
+            mandatory
+            density="compact"
+            color="primary"
+            class="mb-4"
+            @update:model-value="(mode: PromptMode) => setMode(entry, mode)"
+          >
+            <v-btn value="default">
+              {{ $t("group.ai-prompts.mode-default") }}
+            </v-btn>
+            <v-btn value="append">
+              {{ $t("group.ai-prompts.mode-append") }}
+            </v-btn>
+            <v-btn value="override">
+              {{ $t("group.ai-prompts.mode-override") }}
+            </v-btn>
+          </v-btn-toggle>
+
+          <pre v-if="entry.mode !== 'override'" class="ai-prompt-default mb-4">{{ entry.defaultContent }}</pre>
+
+          <v-textarea
+            v-if="entry.mode === 'append'"
+            v-model="entry.appendText"
+            :label="$t('group.ai-prompts.additional-instructions')"
+            auto-grow
+            rows="3"
+            variant="outlined"
+            density="compact"
+          />
+          <v-textarea
+            v-else-if="entry.mode === 'override'"
+            v-model="entry.overrideText"
+            :label="$t('group.ai-prompts.custom-prompt')"
+            auto-grow
+            rows="8"
+            variant="outlined"
+            density="compact"
+          />
+
+          <div class="d-flex pt-2">
+            <BaseButton
+              save
+              class="ml-auto"
+              :disabled="!isDirty(entry)"
+              @click="savePrompt(entry)"
+            />
+          </div>
+        </v-expansion-panel-text>
+      </v-expansion-panel>
+    </v-expansion-panels>
+  </div>
+</template>
+
+<script setup lang="ts">
+import { alert } from "~/composables/use-toast";
+import { useAIPrompts } from "~/composables/use-ai-providers";
+import type { AIPromptOut } from "~/lib/api/types/group";
+
+type PromptMode = "default" | "append" | "override";
+
+interface PromptEntry {
+  name: string;
+  isSystem: boolean;
+  defaultContent: string;
+  defaultChanged: boolean;
+  mode: PromptMode;
+  appendText: string;
+  overrideText: string;
+  // what the server has stored, which the editors are compared against
+  savedMode: PromptMode;
+  savedContent: string;
+}
+
+const GLOBAL_PROMPT_NAME = "global";
+
+const props = defineProps<{
+  groupId?: string;
+}>();
+
+const i18n = useI18n();
+const { prompts, refresh, save, reset } = useAIPrompts(props.groupId);
+
+const entries = ref<PromptEntry[]>([]);
+const globalText = ref("");
+const savedGlobalText = ref("");
+
+function buildEntry(prompt: AIPromptOut): PromptEntry {
+  const mode: PromptMode = prompt.mode ?? "default";
+  const content = prompt.content ?? "";
+  return {
+    name: prompt.name,
+    isSystem: prompt.isSystem,
+    defaultContent: prompt.defaultContent,
+    defaultChanged: !!prompt.defaultChanged,
+    mode,
+    appendText: mode === "append" ? content : "",
+    overrideText: mode === "override" ? content : "",
+    savedMode: mode,
+    savedContent: content,
+  };
+}
+
+// Rebuild the state from what the server has, but leave sections that haven't changed alone so that
+// saving one prompt doesn't discard unsaved edits in the others.
+watch(
+  prompts,
+  (value) => {
+    if (!value) {
+      return;
+    }
+
+    const existing = new Map(entries.value.map(entry => [entry.name, entry]));
+    entries.value = value.prompts.map((prompt) => {
+      const current = existing.get(prompt.name);
+      const savedMode: PromptMode = prompt.mode ?? "default";
+      if (current && current.savedMode === savedMode && current.savedContent === (prompt.content ?? "")) {
+        current.defaultContent = prompt.defaultContent;
+        current.defaultChanged = !!prompt.defaultChanged;
+        return current;
+      }
+      return buildEntry(prompt);
+    });
+
+    const savedGlobal = value.globalInstructions ?? "";
+    if (savedGlobal !== savedGlobalText.value || !existing.size) {
+      globalText.value = savedGlobal;
+    }
+    savedGlobalText.value = savedGlobal;
+  },
+  { immediate: true },
+);
+
+onMounted(() => {
+  refresh();
+});
+
+function setMode(entry: PromptEntry, mode: PromptMode | null) {
+  if (!mode) {
+    return;
+  }
+
+  entry.mode = mode;
+  if (mode === "override" && !entry.overrideText) {
+    entry.overrideText = entry.defaultContent;
+  }
+}
+
+function editorText(entry: PromptEntry) {
+  return entry.mode === "append" ? entry.appendText : entry.overrideText;
+}
+
+function isDirty(entry: PromptEntry) {
+  if (entry.mode !== entry.savedMode) {
+    return true;
+  }
+  return entry.mode !== "default" && editorText(entry) !== entry.savedContent;
+}
+
+const globalDirty = computed(() => globalText.value.trim() !== savedGlobalText.value);
+
+async function savePrompt(entry: PromptEntry) {
+  const result = entry.mode === "default"
+    ? await reset(entry.name)
+    : await save(entry.name, { mode: entry.mode, content: editorText(entry) });
+
+  notify(result);
+}
+
+async function saveGlobal() {
+  const content = globalText.value.trim();
+  const result = content
+    ? await save(GLOBAL_PROMPT_NAME, { mode: "append", content })
+    : await reset(GLOBAL_PROMPT_NAME);
+
+  notify(result);
+}
+
+function notify(result: unknown) {
+  if (result) {
+    alert.success(i18n.t("settings.settings-updated"));
+  }
+  else {
+    alert.error(i18n.t("settings.settings-update-failed"));
+  }
+}
+</script>
+
+<style scoped>
+.ai-prompt-default {
+  white-space: pre-wrap;
+  max-height: 20rem;
+  overflow-y: auto;
+  opacity: 0.7;
+  font-size: 0.8rem;
+}
+</style>
