+/**
+ * A group's AI prompt customizations. Pass a `groupId` to manage another group's prompts as an admin.
+ * Each action resolves to the new prompts, or to null when the request failed.
+ */
+export function useAIPrompts(groupId?: string) {
+  const userApi = useUserApi();
+  const adminApi = groupId ? useAdminApi() : null;
+
+  const prompts = ref<AIPromptsOut | null>(null);
+  const loading = ref(false);
+
+  async function run(request: () => Promise<{ data: AIPromptsOut | null }>): Promise<AIPromptsOut | null> {
+    loading.value = true;
+    try {
+      const { data } = await request();
+      if (data) {
+        prompts.value = data;
+      }
+      return data ?? null;
+    }
+    catch {
+      return null;
+    }
+    finally {
+      loading.value = false;
+    }
+  }
+
+  async function refresh() {
+    return await run(() =>
+      adminApi && groupId ? adminApi.aiProviders.getPrompts(groupId) : userApi.aiProviders.getPrompts(),
+    );
+  }
+
+  async function save(name: string, payload: AIPromptUpdate) {
+    return await run(() =>
+      adminApi && groupId
+        ? adminApi.aiProviders.setPrompt(groupId, name, payload)
+        : userApi.aiProviders.setPrompt(name, payload),
+    );
+  }
+
+  async function reset(name: string) {
+    return await run(() =>
+      adminApi && groupId ? adminApi.aiProviders.resetPrompt(groupId, name) : userApi.aiProviders.resetPrompt(name),
+    );
+  }
+
+  return { prompts, loading, refresh, save, reset };
+}

