+from fastapi import HTTPException, status
+
+from mealie.repos.repository_factory import AllRepositories
+from mealie.schema.group.ai_providers import (
+    AIPromptMode,
+    AIPromptOut,
+    AIPromptOverrideCreate,
+    AIPromptsOut,
+    AIPromptUpdate,
+)
+from mealie.services.openai.openai import GLOBAL_PROMPT_NAME, OpenAIService
+
+
+class AIPromptService:
+    """Manages a group's customizations of the AI prompts"""
+
+    def __init__(self, repos: AllRepositories) -> None:
+        self.repos = repos
+
+    def _validate_name(self, name: str) -> None:
+        if name != GLOBAL_PROMPT_NAME and name not in OpenAIService.get_prompt_names():
+            raise HTTPException(status.HTTP_404_NOT_FOUND, detail=f"Unknown prompt '{name}'")
+
+    def get_prompts(self) -> AIPromptsOut:
+        overrides = {o.name: o for o in self.repos.group_ai_prompt_overrides.get_all()}
+
+        prompts: list[AIPromptOut] = []
+        for name in OpenAIService.get_prompt_names():
+            default_content = OpenAIService.get_default_prompt(name)
+            override = overrides.get(name)
+
+            default_changed = bool(
+                override
+                and override.mode == AIPromptMode.override
+                and override.base_prompt_hash
+                and override.base_prompt_hash != OpenAIService._hash_prompt(default_content)
+            )
+            prompts.append(
+                AIPromptOut(
+                    name=name,
+                    is_system=OpenAIService.is_system_prompt(name),
+                    default_content=default_content,
+                    mode=override.mode if override else None,
+                    content=override.content if override else None,
+                    default_changed=default_changed,
+                )
+            )
+
+        global_instructions = overrides.get(GLOBAL_PROMPT_NAME)
+        return AIPromptsOut(
+            global_instructions=global_instructions.content if global_instructions else None,
+            prompts=prompts,
+        )
+
+    def set_prompt(self, name: str, data: AIPromptUpdate) -> AIPromptsOut:
+        self._validate_name(name)
+
+        if name == GLOBAL_PROMPT_NAME:
+            if data.mode != AIPromptMode.append:
+                raise HTTPException(
+                    status.HTTP_400_BAD_REQUEST, detail="Group-wide instructions can only be appended to prompts"
+                )
+            base_prompt_hash = None
+        else:
+            base_prompt_hash = OpenAIService._hash_prompt(OpenAIService.get_default_prompt(name))
+
+        override = AIPromptOverrideCreate(
+            name=name, mode=data.mode, content=data.content, base_prompt_hash=base_prompt_hash
+        )
+
+        repo = self.repos.group_ai_prompt_overrides
+        existing = next((o for o in repo.get_all() if o.name == name), None)
+        if existing:
+            repo.update(existing.id, override)
+        else:
+            repo.create(override)
+
+        return self.get_prompts()
+
+    def reset_prompt(self, name: str) -> AIPromptsOut:
+        self._validate_name(name)
+
+        repo = self.repos.group_ai_prompt_overrides
+        for existing in repo.get_all():
+            if existing.name == name:
+                repo.delete(existing.id)
+
+        return self.get_prompts()
